import {
  Component,
  Injector,
  OnInit,
  effect,
  inject,
  input,
  signal,
  untracked,
} from '@angular/core';
import { FieldTree, FormField, FormRoot, REQUIRED, form, metadata, validate } from '@angular/forms/signals';
import { Router } from '@angular/router';
import { CLOCK } from '../../core/clock';
import { QuoteStore } from '../../core/quote-store';
import type { FieldConfig, RawValues } from '../../shared/field-config.model';
import { validateField } from '../../shared/field-validators';
import { hydrate } from '../../shared/field-values';

/**
 * The step 1 form (ADR-0004): Signal Forms over the shared validation core. The editing model is
 * `Record<string, string | boolean>` (never null); each field has exactly one `validate()` that
 * calls the pure `validateField`. Built once per instance, hydrated from the wizard state; a
 * different configuration means a new instance (the page recreates it).
 */
@Component({
  selector: 'app-quote-form',
  imports: [FormField, FormRoot],
  templateUrl: './quote-form.html',
  styleUrl: './quote-form.css',
})
export class QuoteForm implements OnInit {
  readonly configs = input.required<FieldConfig[]>();
  readonly countryCode = input.required<string>();

  private readonly injector = inject(Injector);
  private readonly clock = inject(CLOCK);
  private readonly quote = inject(QuoteStore);
  private readonly router = inject(Router);

  protected form!: FieldTree<RawValues>;

  ngOnInit(): void {
    const configs = this.configs();
    const model = signal<RawValues>(hydrate(configs, this.quote.values()));
    this.form = form(
      model,
      (root) => {
        for (const config of configs) {
          validate(root[config.key], ({ value }) => {
            const message = validateField(config, value(), this.clock());
            return message ? { kind: 'custom', message } : undefined;
          });
        }
      },
      {
        injector: this.injector,
        submission: {
          action: async () => {
            if (this.quote.completeStep1(configs) !== null) {
              await this.router.navigate(['/', this.countryCode().toLowerCase(), 'planes']);
            }
            return undefined;
          },
          onInvalid: (root) => {
            const first = configs.find((config) => root[config.key]().invalid());
            if (first) root[first.key]().focusBoundControl();
          },
        },
      },
    );

    // The raw editing values are written to the wizard state on every change (ADR-0003).
    let synced: RawValues = { ...model() };
    effect(
      () => {
        const current = model();
        untracked(() => {
          for (const [key, value] of Object.entries(current)) {
            if (synced[key] !== value) this.quote.setValue(key, value);
          }
          synced = { ...current };
        });
      },
      { injector: this.injector },
    );
  }

  /** The two narrowing accessors of ADR-0004: the only casts, selected by the field type. */
  protected text(key: string): FieldTree<string> {
    return this.form[key] as unknown as FieldTree<string>;
  }
  protected flag(key: string): FieldTree<boolean> {
    return this.form[key] as unknown as FieldTree<boolean>;
  }

  /**
   * The message to show (spec AC-09): input the browser cannot parse never reaches the model (it
   * keeps the last parseable text) but Signal Forms reports a parse error without a message, so
   * that case is evaluated as an empty value: `requiredMessage ?? errorMessage`.
   */
  protected errorOf(config: FieldConfig): string | null {
    const state = this.form[config.key]();
    if (!state.touched() || !state.invalid()) return null;
    const errors = state.errors();
    if (errors.some((error) => error.kind === 'parse')) {
      return validateField(config, '', this.clock()) ?? config.errorMessage;
    }
    return errors[0]?.message ?? null;
  }

  protected describedBy(config: FieldConfig, error: string | null): string | null {
    const ids = [
      config.helpText ? `${config.key}-help` : '',
      error ? `${config.key}-error` : '',
    ].filter(Boolean);
    return ids.length > 0 ? ids.join(' ') : null;
  }
}
<form [formRoot]="form" class="form">
  <p class="form__note">Los campos marcados con * son obligatorios.</p>
  @for (config of configs(); track config.key) {
    @let error = errorOf(config);
    @let described = describedBy(config, error);
    @let id = 'field-' + config.key;
    <div class="field" [class.field--checkbox]="config.type === 'checkbox'">
      @if (config.type === 'checkbox') {
        <input
          type="checkbox"
          [id]="id"
          [formField]="flag(config.key)"
          [attr.aria-required]="config.isRequired"
          [attr.aria-invalid]="error ? 'true' : null"
          [attr.aria-describedby]="described"
        />
        <label [for]="id">{{ config.label }}@if (config.isRequired) {<span aria-hidden="true"> *</span>}</label>
      } @else {
        <label [for]="id">{{ config.label }}@if (config.isRequired) {<span aria-hidden="true"> *</span>}</label>
        @switch (config.type) {
          @case ('select') {
            <select
              [id]="id"
              [formField]="text(config.key)"
              [attr.aria-required]="config.isRequired"
              [attr.aria-invalid]="error ? 'true' : null"
              [attr.aria-describedby]="described"
            >
              <option value="" disabled>Selecciona una opción</option>
              @for (option of config.options; track option.value) {
                <option [value]="option.value">{{ option.label }}</option>
              }
            </select>
          }
          @case ('number') {
            <input
              type="number"
              [id]="id"
              [formField]="text(config.key)"
              [attr.placeholder]="config.placeholder ?? null"
              [attr.aria-required]="config.isRequired"
              [attr.aria-invalid]="error ? 'true' : null"
              [attr.aria-describedby]="described"
            />
          }
          @case ('date') {
            <input
              type="date"
              [id]="id"
              [formField]="text(config.key)"
              [attr.aria-required]="config.isRequired"
              [attr.aria-invalid]="error ? 'true' : null"
              [attr.aria-describedby]="described"
            />
          }
          @default {
            <input
              type="text"
              [id]="id"
              [formField]="text(config.key)"
              [attr.placeholder]="config.placeholder ?? null"
              [attr.aria-required]="config.isRequired"
              [attr.aria-invalid]="error ? 'true' : null"
              [attr.aria-describedby]="described"
            />
          }
        }
      }
      @if (config.helpText) {
        <p class="field__help" [id]="config.key + '-help'">{{ config.helpText }}</p>
      }
      @if (error) {
        <p class="field__error" [id]="config.key + '-error'" role="alert">{{ error }}</p>
      }
    </div>
  }
  <button type="submit" class="form__submit">Continuar</button>
</form>
import { Component, ElementRef, afterNextRender, inject, signal, viewChild } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { CountryStore } from '../../core/country-store';
import { FormFieldStore } from '../../core/form-field-store';
import { QuoteStore } from '../../core/quote-store';
import type { Country } from '../../shared/country.model';
import type { FieldConfig } from '../../shared/field-config.model';
import { LoadError } from '../../shared/load-error';
import { QuoteForm } from './quote-form';

type PageStatus = 'loading' | 'error' | 'ready';

/**
 * Step 1 (`/:country/datos`). Resolves the country from the route, enters its wizard context,
 * loads the field configuration (loading, error and retry states) and hands it to the form.
 */
@Component({
  selector: 'app-quote-form-page',
  imports: [QuoteForm, LoadError],
  templateUrl: './quote-form-page.html',
  styleUrl: './quote-form-page.css',
})
export class QuoteFormPage {
  private readonly route = inject(ActivatedRoute);
  private readonly countries = inject(CountryStore);
  private readonly fields = inject(FormFieldStore);
  private readonly quote = inject(QuoteStore);
  private readonly heading = viewChild.required<ElementRef<HTMLHeadingElement>>('heading');

  protected readonly status = signal<PageStatus>('loading');
  protected readonly configs = signal<FieldConfig[]>([]);
  protected readonly country: Country | undefined = this.countries.find(this.route.snapshot.paramMap.get('country') ?? '');

  constructor() {
    if (this.country) this.quote.enterCountry(this.country.code);
    void this.load();
    // Arriving at the step puts focus on its heading, unless the load already failed
    // (then focus goes to "Reintentar").
    afterNextRender(() => {
      if (this.status() !== 'error') this.heading().nativeElement.focus();
    });
  }

  protected async load(): Promise<void> {
    if (!this.country) {
      this.status.set('error');
      return;
    }
    this.status.set('loading');
    try {
      const configs = await this.fields.load(this.country.code);
      if (configs.length === 0) {
        this.status.set('error');
        return;
      }
      this.quote.prune(configs);
      this.configs.set(configs);
      this.status.set('ready');
    } catch {
      this.status.set('error');
    }
  }
}
